internal static class StandaloneTests {
 internal const string Sample=@"{""data"":{""guide"":{""url"":""parcours-exemple"",""title"":""Parcours fictif de validation"",""description"":""<p>Données de test uniquement</p>"",""objectives"":[{""id"":1,""type"":""title"",""payload"":{""fr"":""Zone de test""}},{""id"":2,""type"":""note"",""payload"":{""fr"":""Point de test [-1,2]""}},{""id"":3,""type"":""quest"",""payload"":10},{""id"":4,""type"":""group"",""payload"":[{""id"":5,""type"":""quest"",""payload"":10}]},{""id"":6,""type"":""choice"",""payload"":[{""condition"":""Classe=Sacri"",""objectives"":[{""id"":7,""type"":""quest"",""payload"":11}]},{""condition"":""Classe=Iop"",""objectives"":[{""id"":8,""type"":""quest"",""payload"":12}]}]}]},""quests"":{""10"":{""name"":{""fr"":""Première quête fictive""},""dplnUrl"":""https://example.com/guide"",""prerequisites"":[{""type"":""quest"",""id"":11}],""objectives"":[{""type"":""note"",""payload"":{""fr"":""Instruction de test""}}],""items"":[{""count"":3,""item"":{""id"":500,""name"":{""fr"":""Ressource fictive""}}}]},""11"":{""name"":{""fr"":""Branche Sacrieur fictive""},""objectives"":[],""items"":[]},""12"":{""name"":{""fr"":""Branche Iop fictive""},""objectives"":[],""items"":[]}},""achievements"":{}}}";

 internal static int ReaderTest(string folder){try{var html=File.ReadAllText(Path.Combine(folder,"page.html"));var normal=GanymedeReader.Normalise(html);var doc=GanymedeReader.Parse(normal,"ganymede-2");var index=new QuestInstructionIndex();index.Add(normal,"ganymede-2");var quest=new TougliStep{QuestId="1631",Title="Réponses à tout"};var matches=index.Match(quest);Check(matches.Count>=2,"Correspondance réelle Réponses à tout");Check(matches.Any(x=>x.Details.Contains("Ganymède")),"Instructions réelles présentes");File.WriteAllText(Path.Combine(folder,"ganymede-result.json"),Store.Json.Serialize(new{title=doc.Title,steps=doc.Steps.Count,coordinates=doc.Steps.Count(x=>x.Coordinates!=""),instructionChars=doc.Steps.Sum(x=>x.Details.Length),questBlocks=index.Items.Count,matchedQuest=quest.Title,matchedInstructions=matches.Count}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"GANYMEDE_FAIL.txt"),ex.ToString());return 1;}}
 static void GanymedeTest(Store store,string folder){var guide=new{id=12,name="Guide fictif",web_description="Exemple de test",user=new{name="Auteur fictif"},steps=new[]{new{id=101,name="",order=1,map="Carte de test",pos_x=-3,pos_y=2,web_text="<p>Parlez au personnage fictif.</p><script>alert(1)</script><p>Choisissez la réponse de test.</p>"},new{id=102,name="Étape de test",order=2,map="Carte de test",pos_x=0,pos_y=0,web_text="<p>Instruction inventée.</p>"}}};var json=Store.Json.Serialize(new{props=new{guide=guide}});var html="<html><script type=\"application/json\" data-page=\"app\">"+json+"</script></html>";var raw=GanymedeReader.Normalise(html);var doc=GanymedeReader.Parse(raw,"ganymede-12");Check(doc.Steps.Count==2&&doc.Steps[0].Coordinates=="-3,2"&&doc.Steps[1].Coordinates=="0,0","Coordonnées Ganymède explicites");Check(doc.Steps[0].Details.Contains("réponse de test")&&!doc.Steps[0].Details.Contains("alert"),"Instructions et retrait scripts");Check(doc.Description.Contains("Auteur fictif")&&GanymedeReader.Url(doc.Slug)=="https://ganymede-app.com/guides/12","Attribution et lien source");Check(GanymedeReader.GuideSlug("https://ganymede-app.com/guides/12?page=2")=="ganymede-12","Lien direct guide");bool rejected=false;try{GanymedeReader.GuideSlug("https://evil.example/guides/12");}catch(InvalidDataException){rejected=true;}Check(rejected,"Source arbitraire refusée");rejected=false;try{GanymedeReader.Parse(raw,"ganymede-13");}catch(InvalidDataException){rejected=true;}Check(rejected,"Guide inattendu refusé");var tree="<script data-page=\"app\">"+Store.Json.Serialize(new{props=new{nodes=new[]{new{hidden=0,guides=new{fr=new{id=12,name="Guide fictif"}}}}}})+"</script>";Check(GanymedeReader.Catalogue(tree).Single().Slug=="ganymede-12","Catalogue français public");var character=DofusCompanion.Character(store.Value);string old=character.guide;PersonalWorkflows.Change(store,()=>character.guide=doc.Slug);TougliReader.Cache(store,doc.Slug,raw);var w=new CompanionWindow(store,true);w.Render(Path.Combine(folder,"ganymede.png"));Find<Button>(w.Content as DependencyObject).First(x=>Equals(x.Content,"Terminé →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(DofusCompanion.Find(store.Value,character).done.Count==1,"Validation réelle Ganymède");var restart=new Store(store.Root);var saved=DofusCompanion.Character(restart.Value);Check(DofusCompanion.Find(restart.Value,saved).done.Count==1,"Reprise Ganymède");PersonalWorkflows.Change(store,()=>DofusCompanion.Character(store.Value).guide=old);Check(DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count==1,"Progression Tougli conservée à part");w.Close();}

 static void AssociationTest(Store store,string folder){var c=DofusCompanion.Character(store.Value);var tougli=TougliReader.Parse(Sample,c);var step=tougli.Steps.First(x=>x.QuestId=="10");Func<int,string> sample=id=>Store.Json.Serialize(new{ganymedeGuide=new{id=id,name="Association de test "+id,author="Auteur fictif",description="Exemple",steps=new[]{new{id=201,name="",order=1,map="Carte fictive",pos_x=-1,pos_y=2,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><div><p>Instruction pour la première quête.</p></div></div><div data-type=\"quest-block\" questname=\"Autre quête\"><p>NE PAS ATTRIBUER CETTE INSTRUCTION.</p></div>"},new{id=202,name="",order=2,map="Carte fictive",pos_x=0,pos_y=0,text="<div data-type=\"quest-block\" questname=\"Première quête fictive\"><p>Suite de la première quête.</p></div>"}}}});
 var index=new QuestInstructionIndex();index.Add(sample(20),"ganymede-20");Check(index.Match(step).Count==2,"Correspondance quête et plusieurs extraits");Check(index.Match(step).All(x=>!x.Details.Contains("NE PAS")),"Instructions d’autre quête exclues");Check(index.Match(new TougliStep{Title="Premiere quete fictive",QuestId="10"}).Count==2,"Accents et casse");Check(index.Match(new TougliStep{Title="Première quête fictiv",QuestId="10"}).Count==0,"Aucune correspondance approximative");Check(index.Match(new TougliStep{Title=step.Title,QuestId=null}).Count==0,"Note Tougli non associée par simple nom");TougliReader.Cache(store,"ganymede-20",sample(20));var p=DofusCompanion.Get(store.Value,c);PersonalWorkflows.Change(store,()=>p.cursor=step.Key);var w=new CompanionWindow(store,true);w.Render(Path.Combine(folder,"tougli-ganymede.png"));Check(Find<TextBlock>(w.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."),"Instructions Ganymède intégrées à la quête Tougli");Find<Button>(w.Content as DependencyObject).First(b=>Equals(b.Content,"Instruction →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Find<TextBlock>(w.Content as DependencyObject).Any(t=>t.Text=="Suite de la première quête."),"Navigation des sous-instructions réelle");Check(DofusCompanion.Current(store.Value,tougli).Key==step.Key&&DofusCompanion.Find(store.Value,c).done.Count==1,"Instruction suivante ne valide pas la quête Tougli");var restarted=new Store(store.Root);Check(restarted.Value.instructions.cursors.Count==1,"Sous-étape sauvegardée");w.Close();index.Add(sample(21),"ganymede-21");Check(index.Match(step).Select(x=>x.GuideSlug).Distinct().Count()==2,"Sources ambiguës conservées séparément");TougliReader.Cache(store,"ganymede-21",sample(21));var ambiguous=new CompanionWindow(store,true);ambiguous.Render(Path.Combine(folder,"association-choice.png"));Check(!Find<TextBlock>(ambiguous.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."),"Source ambiguë non choisie automatiquement");var select=Find<ComboBox>(ambiguous.Content as DependencyObject).Single();select.SelectedIndex=1;Check(Find<TextBlock>(ambiguous.Content as DependencyObject).Any(t=>t.Text=="Instruction pour la première quête."||t.Text=="Suite de la première quête."),"Choix de source réel");ambiguous.Close();}
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject parent) where T:DependencyObject {if(parent is T)yield return (T)parent;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);i++)foreach(var item in Find<T>(System.Windows.Media.VisualTreeHelper.GetChild(parent,i)))yield return item;}
 internal static int Run(string folder){Directory.CreateDirectory(folder);try{var store=new Store(Path.Combine(folder,"isolated-data"));var a=new DofusCharacter{id="a",name="Personnage test",classCode="Sacri",alignment="Bonta",order="CV",guide="parcours-exemple"};var b=new DofusCharacter{id="b",name="Autre personnage",classCode="Iop",guide=a.guide};store.Value.dofus.characters.AddRange(new[]{a,b});store.Value.dofus.active=a.id;store.Save();TougliReader.Cache(store,a.guide,Sample);var doc=TougliReader.Parse(Sample,a);Check(doc.Steps.Count==4&&doc.Steps.Last().Title.Contains("Sacrieur"),"Lecture et choix classe");Check(DofusCompanion.Remaining(store.Value,doc).Single().Count==3,"Déduplication ressources");Check(!TougliReader.Parse(Sample,new DofusCharacter()).Steps.Last().CanComplete,"Choix absent deviné");Check(TougliReader.SafeUrl("javascript:alert(1)")==""&&!TougliReader.ValidSlug("../a"),"Liens et cache");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new CompanionWindow(store,true);window.Render(Path.Combine(folder,"overlay.png"));var finish=Find<Button>(window.Content as DependencyObject).First(x=>Equals(x.Content,"Terminé →"));finish.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Bouton réel valider");Check(DofusCompanion.Current(store.Value,doc).Title.Contains("Première quête"),"Navigation réelle");window.Render(Path.Combine(folder,"overlay-next.png"));DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==2,"Validation");DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Annulation");store.Value.dofus.active=b.id;store.Save();Check(DofusCompanion.Find(store.Value,b)==null,"Indépendance personnage");Check(TougliReader.Parse(Sample,b).Steps.Last().Title.Contains("Iop"),"Autre classe");store.Value.dofus.active=a.id;store.Save();var reopened=new Store(store.Root);Check(DofusCompanion.Find(reopened.Value,DofusCompanion.Character(reopened.Value)).done.Count==1,"Reprise sauvegarde");var tmp=Path.Combine(store.Root,"state.json.tmp");Directory.CreateDirectory(tmp);bool failed=false;try{DofusCompanion.Toggle(store,doc);}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}Directory.Delete(tmp);Check(failed&&DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count==1,"Retour arrière écriture échouée");store.Save();var empty=new CompanionWindow(new Store(Path.Combine(folder,"empty")),true);empty.Render(Path.Combine(folder,"welcome.png"));Check(Find<Button>(empty.Content as DependencyObject).Any(x=>Equals(x.Content,"Personnage · Guides")),"Configuration accessible sans guide");GanymedeTest(store,folder);AssociationTest(store,folder);window.Close();empty.Close();app.Shutdown();File.WriteAllText(Path.Combine(folder,"PASS.txt"),"PASS: exact quest matching, nested quest blocks, exclusion of unrelated quests, ambiguity selection, actual Tougli/Ganymede overlay, real instruction next button without advancing Tougli, persisted substep; Ganymede public page fixture, French catalogue, guide identity, URL filtering, text extraction, source author, coordinates including zero, real Ganymede button, restart and separate Tougli progress; native WPF render; real completion button; API fixture; class selection; unresolved choices; resources; undo; separate characters; restart; failed-save rollback; welcome configuration. No MonEspace data access. Windows installer shortcuts and real game topmost need a user desktop check.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"FAIL.txt"),ex.ToString());return 1;}}
}
